1	/* ============================================================
2	   PORTFOLIO CAROUSEL — portfolio-carousel.module.css
3	   Extracted verbatim from boldteq-v1-0.webflow.css
4	   ============================================================ */
5	
6	.section-regular-2 {
7	  background-color: #fff;
8	  padding: 64px 15% 64px 2%;
9	  position: relative;
10	  overflow: hidden;
11	}
12	
13	.img-slider-sec {
14	  padding-top: 20px;
15	  padding-right: 0%;
16	}
17	
18	.column-4x-large {
19	  grid-column-gap: 80px;
20	  grid-row-gap: 80px;
21	  flex-flow: column;
22	  display: flex;
23	}
24	
25	/* Slider wrapper */
26	.gallery-13-slider {
27	  background-color: #0000;
28	  height: auto;
29	  padding-bottom: 0;
30	  position: relative;
31	  width: 100%;
32	}
33	
34	.gallery-13-mask {
35	  max-width: none;
36	  height: auto;
37	  overflow: hidden;
38	  display: flex;
39	}
40	
41	.gallery-13-slide {
42	  max-width: calc(25% - 12px);
43	  height: 100%;
44	  margin-right: 24px;
45	  flex-shrink: 0;
46	}
47	
48	/* Cards */
49	.gallery-13-card {
50	  aspect-ratio: 1 / 1.25;
51	  border: 1px solid #000;
52	  border-radius: 20px;
53	  width: 100%;
54	  min-height: 392px;
55	  padding: 10px;
56	  position: relative;
57	  overflow: hidden;
58	}
59	
60	.cream {
61	  aspect-ratio: 1 / 1.22;
62	  background-color: #fbf2e4;
63	  border-style: none;
64	  min-height: auto;
65	  padding: 10px;
66	}
67	
68	.light-green {
69	  aspect-ratio: 1 / 1.22;
70	  background-color: #e6fccd;
71	  border-style: none;
72	  min-height: auto;
73	  padding: 10px;
74	}
75	
76	.light-purple {
77	  aspect-ratio: 1 / 1.22;
78	  background-color: #4da1af1a;
79	  border-style: none;
80	  min-height: auto;
81	  padding: 10px;
82	}
83	
84	.light-orange {
85	  aspect-ratio: 1 / 1.22;
86	  background-color: #ff8a8a14;
87	  border-style: none;
88	  min-height: auto;
89	  padding: 10px;
90	}
91	
92	/* Image outer wrapper */
93	.gallery-image-outer {
94	  border-radius: 15px;
95	  margin-bottom: 20px;
96	  padding-top: 20px;
97	  padding-left: 20px;
98	  padding-right: 20px;
99	}
100	
101	.green {
102	  background-color: #0d4a4c;
103	  min-height: auto;
104	}
105	
106	.green-light {
107	  background-color: #abf330;
108	  height: auto;
109	  min-height: auto;
110	}
111	
112	.orange-light {
113	  background-color: #ffc671;
114	  min-height: auto;
115	}
116	
117	.olive-green {
118	  background-color: #5e6350;
119	  min-height: auto;
120	}
121	
122	/* The portfolio image */
123	.image-cover {
124	  object-fit: cover;
125	  object-position: 50% 0%;
126	  border-radius: 10px;
127	  width: 100%;
128	  height: auto;
129	  min-height: auto;
130	  max-height: 357px;
131	  display: block;
132	  position: relative;
133	  overflow: hidden;
134	}
135	
136	.radius-0 {
137	  border-radius: 0;
138	}
139	
140	/* Caption */
141	.gallery-13-caption {
142	  text-align: left;
143	  background-color: #0000;
144	  border-radius: 8px;
145	  height: auto;
146	  padding: 0;
147	  position: relative;
148	  inset: auto;
149	  overflow: visible;
150	}
151	
152	.heading-3 {
153	  color: #082753;
154	  text-align: left;
155	  font-family: 'Roobert PRO', Arial, sans-serif;
156	  font-size: 25px;
157	  font-weight: 700;
158	}
159	
160	/* Color variants for heading-3 */
161	.heading-3-green,
162	.heading-3-green-light,
163	.heading-3-purple {
164	  color: #020e41;
165	  text-align: center;
166	  font-size: 1.3rem;
167	}
168	
169	.heading-3-orange {
170	  color: #111c19;
171	  text-align: center;
172	  -webkit-text-stroke-color: #ff8a8a;
173	  font-size: 1.3rem;
174	}
175	
176	/* Nav buttons */
177	.gallery-13-button {
178	  width: auto;
179	  position: absolute;
180	  inset: auto 0% 0% auto;
181	  top: 50%;
182	  transform: translateY(-50%);
183	  z-index: 10;
184	}
185	
186	.button-left {
187	  left: -1.5%;
188	  right: auto;
189	}
190	
191	.button-right {
192	  right: 0.5%;
193	}
194	
195	.icon-button-outline-large {
196	  color: #000;
197	  background-color: #fff;
198	  border: 1px solid #c9d2d9;
199	  border-radius: 11px;
200	  flex: none;
201	  justify-content: center;
202	  align-items: center;
203	  width: 48px;
204	  height: 48px;
205	  display: flex;
206	  cursor: pointer;
207	}
208	
209	.icon-regular {
210	  width: 24px;
211	  height: 24px;
212	  flex: none;
213	  justify-content: center;
214	  align-items: center;
215	  display: flex;
216	}
217	
218	.icon-blue {
219	  color: #21cfff;
220	}
221	
222	.container-large-2 {
223	  z-index: 1;
224	  width: 100%;
225	  max-width: 1280px;
226	  margin-left: auto;
227	  margin-right: auto;
228	  position: relative;
229	}
230	
231	/* ============================================================
232	   min-width: 1280px
233	   ============================================================ */
234	@media screen and (min-width: 1280px) {
235	  .section-regular-2.img-slider-sec {
236	    padding-right: 0%;
237	  }
238	
239	  .gallery-13-button.button-right {
240	    right: 0.5%;
241	  }
242	
243	  .image-cover {
244	    height: 360px;
245	  }
246	
247	  .image-cover.radius-0 {
