272	    max-width: none;
273	    padding-right: 22%;
274	  }
275	
276	  .section-regular-2.img-slider-sec {
277	    max-width: none;
278	    padding-right: 0%;
279	  }
280	
281	  .gallery-13-button.button-right {
282	    right: 0.5%;
283	  }
284	
285	  .image-cover {
286	    object-fit: cover;
287	    height: 410px;
288	    min-height: auto;
289	    max-height: 420px;
290	    position: static;
291	  }
292	
293	  .image-cover.radius-0 {
294	    height: auto;
295	  }
296	
297	  .gallery-13-slider {
298	    align-self: auto;
299	    max-width: none;
300	  }
301	
302	  .gallery-13-slide {
303	    height: 100%;
304	    min-height: 392px;
305	    position: static;
306	  }
307	
308	  .gallery-13-mask {
309	    height: auto;
310	  }
311	
312	  .gallery-13-card.cream,
313	  .gallery-13-card.light-green,
314	  .gallery-13-card.light-purple,
315	  .gallery-13-card.light-orange {
