/* ============================================================
   PORTFOLIO CAROUSEL — portfolio-carousel.module.css
   Extracted verbatim from boldteq-v1-0.webflow.css
   ============================================================ */

.section-regular-2 {
  background-color: #fff;
  padding: 64px 15% 64px 2%;
  position: relative;
  overflow: hidden;
}

.img-slider-sec {
  padding-top: 20px;
  padding-right: 0%;
}

.column-4x-large {
  grid-column-gap: 80px;
  grid-row-gap: 80px;
  flex-flow: column;
  display: flex;
}

/* Slider wrapper */
.gallery-13-slider {
  background-color: #0000;
  height: auto;
  padding-bottom: 0;
  position: relative;
  width: 100%;
}

/* Mask — overflow visible matches Webflow's .w-slider-mask override */
.gallery-13-mask {
  max-width: none;
  height: auto;
  overflow: visible;
}

/* Slider track — replaces inline style */
.gallery-13-track {
  display: flex;
  gap: 24px;
  height: auto;
}

.gallery-13-slide {
  max-width: calc(25% - 12px);
  height: 100%;
  margin-right: 24px;
  flex-shrink: 0;
}

/* Cards */
.gallery-13-card {
  aspect-ratio: 1 / 1.25;
  border: 1px solid #000;
  border-radius: 20px;
  width: 100%;
  min-height: 392px;
  padding: 10px;
  position: relative;
  overflow: hidden;
}

.cream {
  aspect-ratio: 1 / 1.22;
  background-color: #fbf2e4;
  border-style: none;
  min-height: auto;
  padding: 10px;
}

.light-green {
  aspect-ratio: 1 / 1.22;
  background-color: #e6fccd;
  border-style: none;
  min-height: auto;
  padding: 10px;
}

.light-purple {
  aspect-ratio: 1 / 1.22;
  background-color: #4da1af1a;
  border-style: none;
  min-height: auto;
  padding: 10px;
}

.light-orange {
  aspect-ratio: 1 / 1.22;
  background-color: #ff8a8a14;
  border-style: none;
  min-height: auto;
  padding: 10px;
}

/* Image outer wrapper */
.gallery-image-outer {
  border-radius: 15px;
  margin-bottom: 20px;
  padding-top: 20px;
  padding-left: 20px;
  padding-right: 20px;
}

.green {
  background-color: #0d4a4c;
  min-height: auto;
}

.green-light {
  background-color: #abf330;
  height: auto;
  min-height: auto;
}

.orange-light {
  background-color: #ffc671;
  min-height: auto;
}

.olive-green {
  background-color: #5e6350;
  min-height: auto;
}

/* The portfolio image */
.image-cover {
  object-fit: cover;
  object-position: 50% 0%;
  border-radius: 10px;
  width: 100%;
  height: auto;
  min-height: auto;
  max-height: 357px;
  display: block;
  position: relative;
  overflow: hidden;
}

.radius-0 {
  border-radius: 0;
}

/* Caption */
.gallery-13-caption {
  text-align: left;
  background-color: #0000;
  border-radius: 8px;
  height: auto;
  padding: 0;
  position: relative;
  inset: auto;
  overflow: visible;
}

.heading-3 {
  color: #082753;
  text-align: left;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 25px;
  font-weight: 700;
}

/* Color variants for heading-3 */
.heading-3-green,
.heading-3-green-light,
.heading-3-purple {
  color: #020e41;
  text-align: center;
  font-size: 1.3rem;
}

.heading-3-orange {
  color: #111c19;
  text-align: center;
  -webkit-text-stroke-color: #ff8a8a;
  font-size: 1.3rem;
}

/* Nav buttons */
.gallery-13-button {
  width: auto;
  position: absolute;
  inset: auto 0% 0% auto;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
}

.button-left {
  left: -1.5%;
  right: auto;
}

.button-right {
  right: 0.5%;
}

.icon-button-outline-large {
  color: #000;
  background-color: #fff;
  border: 1px solid #c9d2d9;
  border-radius: 11px;
  flex: none;
  justify-content: center;
  align-items: center;
  width: 48px;
  height: 48px;
  display: flex;
  cursor: pointer;
}

.icon-regular {
  width: 24px;
  height: 24px;
  flex: none;
  justify-content: center;
  align-items: center;
  display: flex;
}

.icon-blue {
  color: #21cfff;
}

.container-large-2 {
  z-index: 1;
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
  position: relative;
}

/* Dot navigation — matches .w-slider-nav + .w-slider-dot from index.html inline style */
.slider-dots {
  justify-content: flex-start;
  align-items: center;
  max-width: calc(100% - 112px);
  margin-left: 0;
  padding-top: 16px;
  padding-bottom: 16px;
  display: flex;
  gap: 4px;
}

.slider-dot {
  height: 12px;
  width: 12px;
  border-radius: 50%;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s;
  background-color: #EDF0F2;
  margin-bottom: 0;
  padding: 0;
  flex-shrink: 0;
}

.slider-dot-active {
  background-color: #000;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .section-regular-2.img-slider-sec {
    padding-right: 0%;
  }

  .gallery-13-button.button-right {
    right: 0.5%;
  }

  /* image-cover.radius-0 keeps height: auto */
  .image-cover {
    height: 360px;
  }

  .image-cover.radius-0 {
    height: auto;
  }

  .gallery-13-slide {
    min-height: 392px;
  }

  .gallery-13-mask {
    height: auto;
  }

  .gallery-13-card.cream,
  .gallery-13-card.light-green,
  .gallery-13-card.light-purple,
  .gallery-13-card.light-orange {
    aspect-ratio: 1 / 1.2;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .section-regular-2 {
    max-width: none;
    padding-right: 22%;
  }

  .section-regular-2.img-slider-sec {
    max-width: none;
    padding-right: 0%;
  }

  .gallery-13-button.button-right {
    right: 0.5%;
  }

  .image-cover {
    object-fit: cover;
    height: 410px;
    min-height: auto;
    max-height: 420px;
    position: static;
  }

  .image-cover.radius-0 {
    height: auto;
  }

  .gallery-13-slider {
    align-self: auto;
    max-width: none;
  }

  .gallery-13-slide {
    height: 100%;
    min-height: 392px;
    position: static;
  }

  .gallery-13-mask {
    height: auto;
  }

  .gallery-13-card.cream,
  .gallery-13-card.light-green,
  .gallery-13-card.light-purple,
  .gallery-13-card.light-orange {
    aspect-ratio: auto;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .section-regular-2.img-slider-sec {
    padding-right: 2%;
  }

  .gallery-13-button.button-left {
    left: -1%;
  }

  .gallery-13-button.button-right {
    right: -1%;
  }

  .column-4x-large {
    grid-column-gap: 64px;
    grid-row-gap: 64px;
  }

  .gallery-13-slide {
    max-width: calc(50% - 12px);
  }

  .gallery-13-mask {
    max-width: none;
    height: auto;
  }

  .gallery-13-card.cream,
  .gallery-13-card.light-green,
  .gallery-13-card.light-purple,
  .gallery-13-card.light-orange {
    aspect-ratio: auto;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .column-4x-large {
    grid-column-gap: 40px;
    grid-row-gap: 40px;
  }

  .gallery-13-slide {
    max-width: calc(50% - 12px);
  }

  .gallery-13-mask {
    max-width: none;
    height: auto;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section-regular-2 {
    padding-top: 60px;
    padding-bottom: 60px;
    padding-left: 4%;
  }

  .section-regular-2.img-slider-sec {
    padding-top: 40px;
    padding-bottom: 50px;
  }

  .gallery-13-button.button-left {
    left: -2.5%;
  }

  .gallery-13-slide {
    max-width: calc(100% - 12px);
    height: 100%;
    margin-right: 15px;
  }

  .gallery-13-mask {
    max-width: none;
    height: auto;
  }

  .heading-3 {
    font-size: 22px;
    line-height: 26px;
  }
}

