}

.paragraph {
  color: #2b2b2b;
  text-align: center;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
}

.center {
  text-align: center;
}

/* Base: 3-column grid */
.feature-grid {
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-rows: auto;
  grid-template-columns: 1fr 1fr 1fr;
  display: grid;
}

/* margin-top-40px modifier preserves 3-col layout and adds margin */
.margin-top-40px {
  grid-column-gap: 20px;
