/* ============================================================
   max-width: 991px
   —
   Webflow rule (line 24558–24564):
     .feature-grid           → grid-template-columns: 1fr
     .feature-grid.margin-top-40px → grid-template-columns: 1fr 1fr 1fr
   Pain Points uses BOTH classes, so the 3-col override applies.
   ============================================================ */
@media screen and (max-width: 991px) {
  /* Generic feature-grid collapses to 1-col */
  .feature-grid {
    grid-template-columns: 1fr;
  }

  /* But feature-grid WITH margin-top-40px stays 3-col (Pain Points uses this) */
  .feature-grid.margin-top-40px {
    grid-template-columns: 1fr 1fr 1fr;
  }

  .section-regular-3 {
    padding-bottom: 0;
  }

  .heading-2.margin-bottom-24px {
    margin-top: 0;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .section-regular-3 {
    padding-top: 0;
