    font-size: 34px;
  }

  .heading-2.margin-bottom-24px {
    font-size: 35px;
    line-height: 45px;
  }

  /* At 767px, margin-top-40px collapses to 1-col (Webflow line 27051) */
  .feature-grid.margin-top-40px {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section-regular-3 {
